// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Roulette} from "../src/Roulette.sol";

contract InvMutTest is Test {
    Roulette c;
    function setUp() public { c = new Roulette{value: 10 ether}(); }

    function testFuzz_property(uint256 ts, uint256 bn) public {
        // Keep timestamps small relative to block numbers so the mutant's
        // stored block number exceeds any subsequent timestamp.
        ts = bound(ts, 1, 1_000_000);
        bn = bound(bn, 1_000_000_000, 2_000_000_000);

        vm.warp(ts);
        vm.roll(bn);

        address actor = address(0xABCD);
        vm.deal(actor, 20 ether);

        // First call: succeeds in both versions (timestamp > 0).
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");

        // Second call in a strictly later block with strictly greater timestamp.
        vm.warp(ts + 1);
        vm.roll(bn + 1);
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");

        // Rule: for every admissible input, both calls must succeed.
        assertTrue(ok1 && ok2);
    }
}
